"""Regenerate reference/INDEX.md. Run from the ui-remix folder: python scripts/build_index.py"""
import os
import re

ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
REF = os.path.join(ROOT, "reference")
out = ["# Reference index\n",
       "Generated by scripts/build_index.py. **CANONICAL** = merged file at a topic's top level; subfolders hold detail files. Merge status: ../SOURCES.md.\n"]
for topic in sorted(os.listdir(REF)):
    tp = os.path.join(REF, topic)
    if not os.path.isdir(tp):
        continue
    out.append(f"\n## {topic}\n")
    for d, _, fs in sorted(os.walk(tp)):
        for f in sorted(fs):
            if not f.endswith(".md"):
                continue
            fp = os.path.join(d, f)
            rel = os.path.relpath(fp, ROOT).replace("\\", "/")
            text = open(fp, encoding="utf8", errors="ignore").read()
            m = re.search(r"(?m)^#\s+(.+)$", text)
            head = m.group(1) if m else f
            canon = " **CANONICAL**" if os.path.dirname(fp) == tp else ""
            out.append(f"- `{rel}` ({os.path.getsize(fp) / 1024:.1f} KB){canon} - {head}")
open(os.path.join(REF, "INDEX.md"), "w", encoding="utf8").write("\n".join(out) + "\n")
print(len(out), "lines")
